func (s *Service) Create(ctx context.Context, githubRepoID int64, clusterSlug, url string) (*MirrorRepo, bool, error) {
	if s.authz == nil {
		// Construction via NewReadOnlyService never wires Create — fail
		// loud at the call site rather than corrupting state on a half-
		// written row + missing SpiceDB grant.
		panic("mirrorrepo: Create requires a non-nil AuthzGranter; service was built with NewReadOnlyService")
	}
	if githubRepoID <= 0 {
		return nil, false, errors.New("mirrorrepo: github_repo_id must be positive")
	}
	if clusterSlug == "" {
		return nil, false, errors.New("mirrorrepo: cluster_slug is required")
	}
	if url == "" {
		return nil, false, errors.New("mirrorrepo: url is required")
	}

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, false, fmt.Errorf("begin: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // rollback after commit is a no-op

	// Allocate a fresh ULID up front; ON CONFLICT-RETURNING gives us
	// back the *existing* id when (github_repo_id, cluster_slug) is
	// already claimed, so the proposed id is discarded and we re-read
	// the live row. id != proposedID iff the conflict fired — that's
	// our "created vs found" signal. (PostgreSQL's xmax trick would
	// work too on PG but not on CockroachDB; the id comparison is
	// portable.)
	proposedID := model.NewRepoID()
	var (
		id        model.RepoID
		createdAt time.Time
	)
	err = tx.QueryRow(ctx,
		`INSERT INTO mirror_repos (id, github_repo_id, cluster_slug)
		 VALUES ($1, $2, $3)
		 ON CONFLICT (github_repo_id, cluster_slug) DO UPDATE
		     SET github_repo_id = EXCLUDED.github_repo_id
		 RETURNING id, created_at`,
		proposedID, githubRepoID, clusterSlug,
	).Scan(&id, &createdAt)
	if err != nil {
		return nil, false, fmt.Errorf("upsert mirror_repos: %w", err)
	}
	created := id == proposedID

	// URL idempotency: succeed if the row already binds to *this* id;
	// fail with ErrURLConflict if it binds to a different mirror.
	tag, err := tx.Exec(ctx,
		`INSERT INTO github_mirror_repo_urls (cluster_slug, url, mirror_repo_id)
		 VALUES ($1, $2, $3)
		 ON CONFLICT (cluster_slug, url) DO NOTHING`,
		clusterSlug, url, id,
	)
	if err != nil {
		return nil, false, fmt.Errorf("insert github_mirror_repo_urls: %w", err)
	}
	if tag.RowsAffected() == 0 {
		// Either we re-ran on the same (id, url) pair (fine) or the
		// URL belongs to a different mirror_repos.id (collision).
		var bound model.RepoID
		if err := tx.QueryRow(ctx,
			`SELECT mirror_repo_id FROM github_mirror_repo_urls
			 WHERE cluster_slug = $1 AND url = $2`,
			clusterSlug, url,
		).Scan(&bound); err != nil {
			return nil, false, fmt.Errorf("verify mirror url binding: %w", err)
		}
		if bound != id {
			return nil, false, fmt.Errorf("%w: cluster=%s url=%s bound to %s, want %s",
				ErrURLConflict, clusterSlug, url, bound, id)
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, false, fmt.Errorf("commit: %w", err)
	}

	// SpiceDB writer grant for the mirror-worker SA. Outside the tx
	// because SpiceDB writes can't join pg transactions. Idempotent
	// on the SpiceDB side (relation upsert), so retries are safe.
	//
	// The repo#platform pointer and the repo#project edge are NOT written
	// here: the mirror-create flow registers this placement as a native repo
	// immediately after (regional.RegisterMirrorAsNativeRepo → authz.RepoCreated),
	// which writes both. This Service only owns the mirror-worker grant.
	if err := s.authz.RepoPermissionGranted(
		ctx, id, "account",
		model.ID(serviceaccount.MirrorWorkerServiceAccountID.String()),
		"writer",
	); err != nil {
		return nil, false, fmt.Errorf("grant mirror-worker writer: %w", err)
	}

	return &MirrorRepo{
		ID:           id,
		GitHubRepoID: githubRepoID,
		ClusterSlug:  clusterSlug,
		CreatedAt:    createdAt,
	}, created, nil
}

// Delete removes the placement row. ON DELETE CASCADE on the URLs FK
// drops every github_mirror_repo_urls row pointing at this id. This does
// NOT touch SpiceDB: the mirror's repo#… relations (project edge, platform
// pointer, mirror-worker writer grant) are cleared by the native-repo
// teardown (regional.DeleteRepo → authz.RepoDeleted), which the delete flow
// runs alongside this. Calling Delete in isolation leaves those tuples for
// SpiceDB's lazy GC.
//
// Idempotent: deleting a missing row returns ErrNotFound so the
// caller (DeleteMirrorPlacement) can map to 404; callers that want a
// "delete-if-exists" can suppress the sentinel.
func (s *Service) Delete(ctx context.Context, id model.RepoID) error {
	tag, err := s.pool.Exec(ctx, `DELETE FROM mirror_repos WHERE id = $1`, id)
	if err != nil {
		return fmt.Errorf("delete mirror: %w", err)
	}

const maxConsecutivePollErrors = 5

var (
	// errMirrorCloneFailed reports the mirror's initial clone reached the
	// terminal "failed" status — the server gave up cloning the upstream.
	errMirrorCloneFailed = errors.New("initial clone failed")
	// errMirrorSuspended reports the placement is suspended: registered, but the
	// cluster won't serve it. Recovery is operator-side (explainSuspendedMirror).
	errMirrorSuspended = errors.New("mirror is suspended")
)

// mirrorStatusGetter is the slice of *coreapi.Client that awaitMirrorReady
// needs, declared as an interface so the poll is unit-testable with a fake.
type mirrorStatusGetter interface {
	GetMirror(ctx context.Context, params coreapi.GetMirrorParams) (*coreapi.Mirror, error)
}

// awaitMirrorReady polls the control plane for a mirror's clone lifecycle until
// it reaches a terminal status or the deadline/cancellation fires. It returns
// the last observed status plus:
//
//   - nil                     when ready (the repo is clonable)
//   - errMirrorCloneFailed    when the initial clone failed
//   - errMirrorSuspended      when the placement is suspended
//   - a timeout/transport err when the wait deadline passed, or polls kept
//     erroring past maxConsecutivePollErrors (transient glitches are retried)
//
// "processing" keeps the loop running. This replaces the old smart-HTTP
// info/refs probe: the control plane now reports clone readiness directly via
// Mirror.status, so a single authenticated control-plane call per tick suffices
// — no repo-scoped token exchange or data-plane round trip.
//
// onStatus (may be nil) is invoked with each observed status so callers can show
// live per-mirror progress (e.g. the wizard's Docker-style line list).
func awaitMirrorReady(ctx context.Context, c mirrorStatusGetter, mirrorID string, timeout time.Duration, onStatus func(coreapi.MirrorStatus)) (coreapi.MirrorStatus, error) {
	if timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, timeout)
		defer cancel()
	}
	ticker := time.NewTicker(mirrorPollInterval)
	defer ticker.Stop()

	var last coreapi.MirrorStatus
	var consecutiveErrs int
	for {
		m, err := c.GetMirror(ctx, coreapi.GetMirrorParams{MirrorId: mirrorID})
		switch {
		case err != nil:
			if ctx.Err() != nil {
				return last, classifyWaitContextErr(ctx.Err())
			}
			// Tolerate transient glitches: the clone may still be progressing,
			// so retry on the next tick. Only give up once errors persist.
			consecutiveErrs++
			if consecutiveErrs >= maxConsecutivePollErrors {
				return last, fmt.Errorf("poll mirror status: %w", err)
			}
		default:
			consecutiveErrs = 0
			if s, ok := m.Status.Get(); ok {
				last = s
				if onStatus != nil {
					onStatus(s)
				}
				switch s {
				case coreapi.MirrorStatusReady:
					return s, nil
				case coreapi.MirrorStatusFailed:
					return s, errMirrorCloneFailed
				case coreapi.MirrorStatusSuspended:
					return s, errMirrorSuspended
				case coreapi.MirrorStatusProcessing:
					// keep waiting
				}
			}
		}
		select {
		case <-ctx.Done():
			return last, classifyWaitContextErr(ctx.Err())
		case <-ticker.C:
		}
	}
}

// classifyWaitContextErr maps the clone wait's context error to a user-facing
// error: a user Ctrl+C exits quietly (SilentError, so main.go doesn't reprint
// it), while a real deadline reports the timeout.
func classifyWaitContextErr(err error) error {
	if errors.Is(err, context.Canceled) {
		return NewSilentError(err)
	}
	return fmt.Errorf("timed out waiting for initial clone: %w", err)
}

// explainSuspendedMirror tells the user a suspended placement can't be served
// and to contact support. Suspension usually follows a loss of upstream GitHub
// access (App uninstalled, repo went private, or a transient API error); the
// fix is operator-side, so we point at support rather than leaking an internal
// admin command.
func explainSuspendedMirror(w io.Writer, mirrorID string) {
	fmt.Fprintf(w,
		"\nMirror %s is registered but suspended, so it can't be cloned yet.\n"+
			"This usually means upstream GitHub access was lost (App uninstalled,\n"+
			"the repo went private, or a transient API error). Contact support to\n"+
			"restore it.\n",
		mirrorID)
}

