package corev1

import "time"

// Mirror is the wire representation of one mirror placement.
type Mirror struct {
	MirrorID       string     `json:"mirrorId"`
	Provider       string     `json:"provider"`
	Owner          string     `json:"owner"`
	Repo           string     `json:"repo"`
	ClusterHost    string     `doc:"Public host of the cluster serving this mirror."                                                       json:"clusterHost"`
	Jurisdiction   string     `json:"jurisdiction,omitempty"`
	Cell           string     `doc:"Physical cell the mirror's cluster runs in, e.g. aws-us-east-2."                                       json:"cell,omitempty"`
	InstallationID int64      `json:"installationId,omitempty"`
	IsPrivate      bool       `json:"isPrivate,omitempty"`
	IsArchived     bool       `json:"isArchived,omitempty"`
	CreatedAt      time.Time  `format:"date-time"                                                                                          json:"createdAt"`
	SuspendedAt    *time.Time `format:"date-time"                                                                                          json:"suspendedAt,omitempty"`
	Status         string     `doc:"Clone lifecycle: processing (cloning), ready (clonable), failed (initial clone failed), or suspended." enum:"processing,ready,failed,suspended" json:"status,omitempty"`
}

// ListMirrorsInput is the input for GET /api/v1/mirrors.
type ListMirrorsInput struct {
	PageInput

	Cluster  string `doc:"Optional: restrict to mirrors on this cluster (public host, e.g. royalcanin.partial.to). Case-sensitive exact match." query:"cluster"`
	Provider string `doc:"Optional: restrict to mirrors of this upstream provider, case-insensitive (e.g. \"github\")."                         query:"provider"`
	Owner    string `doc:"Optional: restrict to mirrors with this upstream owner login (case-insensitive)."                                     query:"owner"`
}

// ListMirrorsOutput is the response for the mirror list. NextPageToken is set
// when more pages remain; pass it back as ?pageToken for the next page.
type ListMirrorsOutput struct {
	Body struct {
		PageMeta

		Mirrors []Mirror `json:"mirrors"`
	}
}

// AvailableMirror is one GitHub repo the caller could onboard as a mirror,
// surfaced by GET /api/v1/mirrors/available. Status distinguishes a repo the
// caller can onboard ("available"), one already mirrored ("mirrored"), and a
// personal repo owned by someone else that only its owner may mirror
// ("owner-only").
type AvailableMirror struct {
	Owner      string `json:"owner"`
	Repo       string `json:"repo"`
	IsPrivate  bool   `json:"isPrivate,omitempty"`
	IsArchived bool   `json:"isArchived,omitempty"`
	Access     string `doc:"Caller's effective GitHub access: read, write, or admin."                                             enum:"read,write,admin"              json:"access"`
	Status     string `doc:"available (can onboard), mirrored (already mirrored), or owner-only (personal repo of another user)." enum:"available,mirrored,owner-only" json:"status"`
}

// ListAvailableMirrorsInput is the input for GET /api/v1/mirrors/available.
type ListAvailableMirrorsInput struct {
	Owner string `doc:"Optional: restrict to repos with this owner login (case-insensitive)." query:"owner"`
}

// ListAvailableMirrorsOutput is the response for the available-mirror listing.
type ListAvailableMirrorsOutput struct {
	Body struct {
		Available []AvailableMirror `json:"available"`
	}
}

// GetMirrorInput is the path key for GET /api/v1/mirrors/{mirrorId}.
type GetMirrorInput struct {
	MirrorID string `path:"mirrorId" pattern:"^[0-9A-HJKMNP-TV-Z]{26}$"`
}

// GetMirrorOutput is the response for the single-mirror get.
type GetMirrorOutput struct {
	Body Mirror
}

// CreateMirrorInput is the body for POST /api/v1/mirrors.
type CreateMirrorInput struct {
	Body struct {
		Provider    string `enum:"github"                                                                                           json:"provider"    required:"true"`
		Owner       string `json:"owner"                                                                                            minLength:"1"      required:"true"`
		Repo        string `json:"repo"                                                                                             minLength:"1"      required:"true"`
		ClusterHost string `doc:"Destination cluster, as either a bare DNS host or the publicUrl returned by GET /api/v1/clusters." json:"clusterHost" minLength:"1"   required:"true"`
	}
}

// CreatedMirror describes the new placement.
type CreatedMirror struct {
	MirrorID  string `json:"mirrorId"`
	MirrorURL string `json:"mirrorUrl"`
	PublicURL string `json:"publicUrl"`
	Created   bool   `doc:"true on fresh creation; false when an existing mirror was returned." json:"created"`
	Empty     bool   `doc:"true when the upstream has no refs to clone."                        json:"empty"`
}

// CreateMirrorOutput is the response.
type CreateMirrorOutput struct {
	Status int
	Body   CreatedMirror
}

// DeleteMirrorInput keys DELETE /api/v1/mirrors on the upstream coords +
// targeted cluster host — the same shape CreateMirror takes, so create and
// delete address a placement identically.
type DeleteMirrorInput struct {
	Provider    string `enum:"github"                                        query:"provider" required:"true"`
	Owner       string `minLength:"1"                                        query:"owner"    required:"true"`
	Repo        string `minLength:"1"                                        query:"repo"     required:"true"`
	ClusterHost string `doc:"Public host of the cluster serving the mirror." minLength:"1"    query:"clusterHost" required:"true"`
}

// DeleteMirrorOutput is empty (204).
type DeleteMirrorOutput struct {
	Status int
}

// MirrorCollaborator is one principal with effective access to a mirror.
type MirrorCollaborator struct {
	AccountID string `json:"accountId"`
	Handle    string `doc:"Primary handle (provider:label), empty if none resolves." json:"handle,omitempty"`
	Role      string `doc:"reader (pull) or writer (pull+push)."                     json:"role"`
}

// ListMirrorCollaboratorsInput keys GET /api/v1/mirrors/collaborators on the
// upstream coords + cluster host.
type ListMirrorCollaboratorsInput struct {
	Provider    string `enum:"github"                                        query:"provider" required:"true"`
	Owner       string `minLength:"1"                                        query:"owner"    required:"true"`
	Repo        string `minLength:"1"                                        query:"repo"     required:"true"`
	ClusterHost string `doc:"Public host of the cluster serving the mirror." minLength:"1"    query:"clusterHost" required:"true"`
}

// ListMirrorCollaboratorsOutput is the response.
type ListMirrorCollaboratorsOutput struct {
	Body struct {
		Collaborators []MirrorCollaborator `json:"collaborators"`
	}
}

