// auth-gate circuit breaker: once MarkSuspended stamps the row,
// LookupRefByURL must return ErrNotFound so STS's mirror token
// exchange refuses with invalid_target. Without this filter, cached
// edges in github_user_repo_access would still let existing users
// mint mirror tokens against a known-broken upstream.
func TestLookupRefByURL_SkipsSuspended(t *testing.T) {
	pool := newPool(t)
	svc := mirrorrepo.NewService(pool, noopAuthz{})
	ctx := context.Background()

	githubRepoID := uniqueID()
	owner := "skip-suspended-url-" + t.Name()
	repo := "r"
	clusterSlug := "test-cluster-" + t.Name()
	mirrorID := seedRepoAndPlacement(t, pool, githubRepoID, owner, repo, clusterSlug)

	url := mirrorrepo.MirrorURL(owner, repo)

	// Pre-suspension: the lookup resolves.
	ref, err := svc.LookupRefByURL(ctx, clusterSlug, url)
	if err != nil {
		t.Fatalf("LookupRefByURL (pre-suspension): %v", err)
	}
	if ref.MirrorRepoID != mirrorID {
		t.Fatalf("got %s, want %s", ref.MirrorRepoID, mirrorID)
	}

	// Stamp suspended_at.
	if err := svc.MarkSuspended(ctx, mirrorID, time.Now()); err != nil {
		t.Fatalf("MarkSuspended: %v", err)
	}

	// Post-suspension: still ErrNotFound under errors.Is (the safe
	// default every caller relies on) but carrying the typed
	// SuspendedError so STS can explain the refusal.
	_, err = svc.LookupRefByURL(ctx, clusterSlug, url)
	if !errors.Is(err, mirrorrepo.ErrNotFound) {
		t.Fatalf("LookupRefByURL (post-suspension) = %v, want ErrNotFound", err)
	}
	var susp *mirrorrepo.SuspendedError
	if !errors.As(err, &susp) {
		t.Fatalf("LookupRefByURL (post-suspension) = %v, want *SuspendedError", err)
	}
	if susp.Ref.MirrorRepoID != mirrorID || susp.SuspendedAt.IsZero() {
		t.Errorf("SuspendedError = %+v, want ref %s with non-zero SuspendedAt", susp, mirrorID)
	}
}

