	}
	for _, tt := range tests {
		t.Run(tt.in, func(t *testing.T) {
			t.Parallel()
			got, err := parseMirrorRole(tt.in)
			if tt.wantErr {
				if err == nil {
					t.Errorf("parseMirrorRole(%q) = nil error, want error", tt.in)
				}
				return
			}
			if err != nil {
				t.Fatalf("parseMirrorRole(%q) = %v, want nil", tt.in, err)
			}
			if got != tt.want {
